// يتحقق من توقيع المنصة (HMAC-SHA256 على `${ts}.${body}`) ونافذة الوقت، ويرفض غير ذلك.
// السر من متغير بيئة n8n (AE_N8N_OUTBOUND_SECRET، hex). في الإنتاج: من مدير أسرار n8n.
const crypto = require('crypto');
const req = $input.first().json;
const h = req.headers || {};
const ts = Number(h['x-ae-timestamp']);
const body = JSON.stringify(req.body);
const secret = Buffer.from($env.AE_N8N_OUTBOUND_SECRET, 'hex');
const expected = 'v1=' + crypto.createHmac('sha256', secret).update(`${ts}.${body}`).digest('hex');
const got = String(h['x-ae-signature'] || '');
const fresh = Math.abs(Date.now() / 1000 - ts) <= 300;
const verified = fresh && got.length === expected.length && crypto.timingSafeEqual(Buffer.from(got), Buffer.from(expected));
if (!verified) throw new Error('AE signature verification failed');
// هنا تأتي خطوة الإرسال الفعلية (Email/Outlook node) في نشر حقيقي. هذا السير يعيد ما سيُرسل فقط.
return [{ json: { verified, idempotencyKey: h['idempotency-key'], workflowKey: req.body.workflowKey, approvalId: req.body.approvalId, payload: req.body.payload, action: 'remittance_notice_prepared' } }];
